;560:/*
;561: * There was a sign extension bug in older revisions of this function.  While
;562: * we would have liked to simply fix the bug and move on, we have to provide
;563: * a backwards compatibility feature (essentially the bug) for some systems and
;564: * a safety measure for some others.  The latter is needed because for certain
;565: * multiple inputs to the buggy algorithm there exist easily found inputs to
;566: * the correct algorithm that produce the same hash.  Thus, we optionally
;567: * deviate from the correct algorithm just enough to avoid such collisions.
;568: * While the bug itself affected the majority of passwords containing
;569: * characters with the 8th bit set (although only a percentage of those in a
;570: * collision-producing way), the anti-collision safety measure affects
;571: * only a subset of passwords containing the '\xff' character (not even all of
;572: * those passwords, just some of them).  This character is not found in valid
;573: * UTF-8 sequences and is rarely used in popular 8-bit character encodings.
;574: * Thus, the safety measure is unlikely to cause much annoyance, and is a
;575: * reasonable tradeoff to use when authenticating against existing hashes that
;576: * are not reliably known to have been computed with the correct algorithm.
;577: *
;578: * We use an approach that tries to minimize side-channel leaks of password
;579: * information - that is, we mostly use fixed-cost bitwise operations instead
;580: * of branches or table lookups.  (One conditional branch based on password
