;814:/*
;815: * Please preserve the runtime self-test.  It serves two purposes at once:
;816: *
;817: * 1. We really can't afford the risk of producing incompatible hashes e.g.
;818: * when there's something like gcc bug 26587 again, whereas an application or
;819: * library integrating this code might not also integrate our external tests or
;820: * it might not run them after every build.  Even if it does, the miscompile
;821: * might only occur on the production build, but not on a testing build (such
;822: * as because of different optimization settings).  It is painful to recover
;823: * from incorrectly-computed hashes - merely fixing whatever broke is not
;824: * enough.  Thus, a proactive measure like this self-test is needed.
;825: *
;826: * 2. We don't want to leave sensitive data from our actual password hash
;827: * computation on the stack or in registers.  Previous revisions of the code
;828: * would do explicit cleanups, but simply running the self-test after hash
;829: * computation is more reliable.
;830: *
;831: * The performance cost of this quick self-test is around 0.6% at the "$2a$08"
;832: * setting.
